function referenceMatches(region,query,area,fields){
  return (region==="All regions" || region===area) && fields.join(" ").toLowerCase().includes(query);
}
function appendReferenceEntries(region,query){
  const list=$("entries");
  let found=0;
  function entry(name,meta){
    if(!found++)list.append(node("h3","Illustrated references"));
    const detail=node("details"),summary=node("summary"),body=node("div",undefined,"entry-body");
    summary.append(node("strong",name),node("span",meta));detail.append(summary,body);list.append(detail);
    return {body,detail};
  }
  for(const [name,area,target,path] of clinicalReferences){
    if(!referenceMatches(region,query,area,[name,area,target,"AAOS"]))continue;
    entry(name,target).body.append(link("AAOS illustrated technique guide",path.startsWith("https:")?path:"https://www.orthoinfo.org/bodypart/"+path));
  }
  for(const [name,area,target,slug] of yogaReferences){
    if(!referenceMatches(region,query,area,[name,area,target,"yoga"]))continue;
    entry(name,target).body.append(link("Yoga Journal · pose and variations","https://www.yogajournal.com/poses/"+slug+"/"));
  }
  for(const [id,name,muscle,method,gear,photos] of exerciseReferences){
    const area=muscleRegions[muscle]||"Upper body";
    if(!referenceMatches(region,query,area,[name,muscle,area,method,gear]))continue;
    const {detail,body}=entry(name,muscle+" · "+method);
    const base="https://raw.githubusercontent.com/yuhonas/free-exercise-db/"+exerciseRevision+"/exercises/";
    body.append(node("p",method+(gear&&gear!=="body only"?" · Equipment: "+gear:"")),link("Free Exercise DB · original instructions","https://github.com/yuhonas/free-exercise-db/blob/"+exerciseRevision+"/exercises/"+id+".json"));
    detail.ontoggle=()=>{
      if(!detail.open||body.querySelector("figure"))return;
      const figure=node("figure",undefined,"study-photos");
      photos.forEach((path,i)=>{
        const image=node("img");image.alt=name+", reference view "+(i+1);image.loading="lazy";image.src=base+path;
        figure.append(image);
      });
      body.append(figure);
    };
  }
}
